import os
import torch


class Config:
    # --------------------------------------------------------------------------
    # 1. Paths & Directories
    # --------------------------------------------------------------------------
    # Root directory for input data
    INPUT_DIR = "./input"

    # Metadata paths (generated by the provided script)
    METADATA_DIR = "./metadata"
    TRAIN_CSV = os.path.join(METADATA_DIR, "train.csv")
    VAL_CSV = os.path.join(METADATA_DIR, "val.csv")
    TEST_CSV = os.path.join(METADATA_DIR, "test.csv")

    # Working directory for caching processed data and saving models
    # Using 'idea_47' as the specific iteration identifier
    WORKING_DIR = "./working/idea_47"

    # Ensure the working directory exists
    os.makedirs(WORKING_DIR, exist_ok=True)

    # Path to save the best model checkpoint
    BEST_MODEL_PATH = os.path.join(WORKING_DIR, "best_model.pth")

    # Path to save the submission file
    SUBMISSION_PATH = "./submission/submission.csv"
    # Ensure submission directory exists
    os.makedirs(os.path.dirname(SUBMISSION_PATH), exist_ok=True)

    # --------------------------------------------------------------------------
    # 2. Data Pipeline Parameters
    # --------------------------------------------------------------------------
    # Image dimensions (224x224 for EfficientNet-B0)
    IMG_SIZE = 224

    # Modalities available in the dataset
    MODALITIES = ["FLAIR", "T1w", "T1wCE", "T2w"]

    # Stacking logic: Anchor - 5, Anchor, Anchor + 5
    STRIDE = 5
    NUM_SLICES_PER_MODALITY = 3

    # Total input channels = 4 modalities * 3 slices = 12 channels
    INPUT_CHANNELS = len(MODALITIES) * NUM_SLICES_PER_MODALITY

    # ROI Selection: Restrict search to 15% - 85% depth to avoid skull/neck artifacts
    ROI_DEPTH_START = 0.15
    ROI_DEPTH_END = 0.85

    # Circuit breaker threshold (abort if >1% data corrupt)
    CORRUPTION_THRESHOLD = 0.01

    # --------------------------------------------------------------------------
    # 3. Model & Training Hyperparameters
    # --------------------------------------------------------------------------
    MODEL_NAME = "efficientnet_b0"

    # Training settings
    BATCH_SIZE = 32
    EPOCHS = 20

    # Optimization (AdamW)
    LEARNING_RATE = 1e-4
    WEIGHT_DECAY = 1e-2

    # Early Stopping
    PATIENCE = 5

    # Reproducibility
    SEED = 42

    # Compute
    NUM_WORKERS = 4
    DEVICE = "cuda" if torch.cuda.is_available() else "cpu"

    # Augmentation
    ROTATION_DEGREES = 15  # +/- 15 degrees

    # Inference
    USE_TTA = True  # Use Test-Time Augmentation (Horizontal/Vertical Flips)
